// Pages WebSocket entry for the existing Tokyo VPS.
// Existing WebSocket forwarding and private encrypted profile downloads.
// sslip.io resolves this fixed hostname to the embedded VPS address.
// Workers fetch requires a hostname; the retired domain is not used.
const UPSTREAM_ORIGIN = 'http://152.32.147.128.sslip.io';
const WS_PATH_SHA256 = 'cbf7a27e2bfe7b8fe8f29f25ca81e1006bcdfb5fc7e54921aa30a1aaf4a27d8c';
const FORWARDED_HEADERS = [
  'Upgrade', 'Connection', 'Sec-WebSocket-Key', 'Sec-WebSocket-Version',
  'Sec-WebSocket-Protocol', 'Sec-WebSocket-Extensions', 'User-Agent',
];

function emptyResponse(status) {
  return new Response(null, {
    status,
    headers: { 'Cache-Control': 'no-store', 'X-Content-Type-Options': 'nosniff' },
  });
}

async function sha256(text) {
  const bytes = await crypto.subtle.digest('SHA-256', new TextEncoder().encode(text));
  return Array.from(new Uint8Array(bytes), byte => byte.toString(16).padStart(2, '0')).join('');
}


// Only authenticated ciphertext is stored in the public source. The 256-bit
// decryption capability is supplied by the private download URL, never here.
const ENCRYPTED_PROFILE_BUNDLE = '';
const PROFILE_AAD = new TextEncoder().encode('private-profiles-v1');

function base64Bytes(text) {
  return Uint8Array.from(atob(text), ch => ch.charCodeAt(0));
}

async function profileResponse(request, url) {
  const match = /^\/profiles\/([A-Za-z0-9_-]{43})\/(desktop|android|stash|auto)\.yaml$/.exec(url.pathname);
  if (!match || !['GET', 'HEAD'].includes(request.method) || url.search ||
      url.protocol !== 'https:' || request.headers.has('Upgrade')) return emptyResponse(404);
  try {
    const keyText = match[1].replace(/-/g, '+').replace(/_/g, '/') + '=';
    const rawKey = base64Bytes(keyText);
    const key = await crypto.subtle.importKey('raw', rawKey, 'AES-GCM', false, ['decrypt']);
    const packed = base64Bytes(ENCRYPTED_PROFILE_BUNDLE);
    const decrypted = await crypto.subtle.decrypt({
      name: 'AES-GCM', iv: packed.slice(0, 12), additionalData: PROFILE_AAD, tagLength: 128,
    }, key, packed.slice(12));
    const decompressed = new Blob([decrypted]).stream().pipeThrough(new DecompressionStream('gzip'));
    const bundle = await new Response(decompressed).json();
    if (bundle.version !== 1) return emptyResponse(404);
    let target = match[2];
    if (target === 'auto') {
      const agent = (request.headers.get('User-Agent') || '').toLowerCase();
      target = agent.includes('stash') ? 'stash' :
        (agent.includes('flclash') || agent.includes('android')) ? 'android' : 'desktop';
    }
    const text = bundle.files[target];
    if (typeof text !== 'string') return emptyResponse(404);
    const bytes = new TextEncoder().encode(text);
    return new Response(request.method === 'HEAD' ? null : bytes, {
      status: 200,
      headers: {
        'Content-Type': 'application/yaml; charset=utf-8',
        'Content-Length': String(bytes.byteLength),
        'Content-Disposition': `attachment; filename="AI-ToLink-Liangxin-${target}.yaml"`,
        'Cache-Control': 'private, no-store, max-age=0',
        'Referrer-Policy': 'no-referrer',
        'X-Content-Type-Options': 'nosniff',
        'Profile-Update-Interval': '24',
      },
    });
  } catch {
    return emptyResponse(404);
  }
}

export default {
  async fetch(request) {
    const url = new URL(request.url);
    if (url.pathname.startsWith('/profiles/')) return profileResponse(request, url);
    if (request.method !== 'GET' ||
        request.headers.get('Upgrade')?.toLowerCase() !== 'websocket' ||
        url.search || await sha256(url.pathname) !== WS_PATH_SHA256) {
      return emptyResponse(404);
    }

    const headers = new Headers();
    for (const name of FORWARDED_HEADERS) {
      const value = request.headers.get(name);
      if (value !== null) headers.set(name, value);
    }
    headers.set('Host', new URL(UPSTREAM_ORIGIN).hostname);
    headers.set('Upgrade', 'websocket');
    headers.set('Connection', 'Upgrade');

    try {
      const upstream = await fetch(new URL(url.pathname, UPSTREAM_ORIGIN), {
        method: 'GET', headers, redirect: 'manual',
      });
      // Return the original response to preserve the WebSocket connection.
      return upstream.status === 101 ? upstream : emptyResponse(502);
    } catch {
      return emptyResponse(502);
    }
  },
};

